diff --git a/packages/server/src/utils/relationship-validation.ts b/packages/server/src/utils/relationship-validation.ts
index 71b4f42b0..f0cc3d43a 100644
--- a/packages/server/src/utils/relationship-validation.ts
+++ b/packages/server/src/utils/relationship-validation.ts
@@ -17,6 +17,53 @@ const CALLER_SETTABLE_SOURCES = ['ui', 'llm', 'feed', 'api'] as const;
 export const EDGE_SOURCE_CONFIG = 'config';
 export const EDGE_SOURCE_MANUAL = 'manual';

+/**
+ * System-controlled classification of what a relationship type is FOR.
+ *
+ * `authorization` marks a type the ACL gates read. It is deliberately not
+ * caller-settable: the whole point is that the platform, not a caller or a
+ * connector manifest, decides which vocabulary grants access.
+ */
+export type RelationshipTypePurpose = 'authorization';
+export const PURPOSE_AUTHORIZATION: RelationshipTypePurpose = 'authorization';
+
+/**
+ * Slugs the ACL engine owns. Reserved so an org cannot create one for ordinary
+ * domain modelling and have `ensureMemberOfType` adopt it into the access path —
+ * that statement upserts on (organization_id, slug), so an org-authored row with
+ * this slug WOULD be adopted.
+ *
+ * This list is a creation-time reservation, not the enforcement boundary. The
+ * boundary is `purpose`: a type is refused to callers because it is CLASSIFIED
+ * authorization, not because its slug matched a string. The reservation exists
+ * so the classified row can only ever have been minted by the platform.
+ */
+const RESERVED_AUTHORIZATION_SLUGS = new Set(['member_of']);
+
+export function isReservedAuthorizationSlug(slug: string): boolean {
+  return RESERVED_AUTHORIZATION_SLUGS.has(slug);
+}
+
+/**
+ * Refuse a caller-driven mutation of an authorization-bearing relationship type.
+ *
+ * Without this, classifying `member_of` would make the ACL gates depend on rows
+ * that any caller holding the generic entity-link surface could create or
+ * soft-delete — i.e. classification alone would hand out a way to mint or revoke
+ * access. Applies to link, update_link, unlink, and the schema lifecycle.
+ */
+export function assertNotAuthorizationType(
+  type: { slug?: string | null; purpose?: string | null },
+  action: string
+): void {
+  if (type.purpose !== PURPOSE_AUTHORIZATION) return;
+  throw new ToolUserError(
+    `Relationship type '${type.slug ?? 'unknown'}' is authorization-bearing and cannot be modified via ${action}. ` +
+      'Access-granting edges are maintained by the connector ACL syncs.',
+    403
+  );
+}
+
 /** Source values used to select edges during reconciliation. */
 const RECONCILED_SOURCES = [EDGE_SOURCE_CONFIG, EDGE_SOURCE_MANUAL] as const;

diff --git a/packages/server/src/__tests__/integration/authz/authorization-type-guards.test.ts b/packages/server/src/__tests__/integration/authz/authorization-type-guards.test.ts
