  1396			windowId: ctx.actingWindowId ?? args?.automation_source?.window_id ?? null,
  1397			principalId: deleteActor.id,
  1398			ownerAgentId: deleteActor.ownerAgentId,
  1399			ownerResolved: deleteActor.ownerResolved,
  1400			entityTypeSlug: entity.entity_type,
  1401			entityId,
  1402			entityOrgId: null,
  1403			forceDeleteTree: force,
  1404			current,
  1405		});
  1406		if (deleteDecision.outcome === "deny") {
  1407			throw new ToolUserError(deleteDecision.reason, 403);
  1408		}
  1409		// Preflight: report what the delete would remove/detach without mutating.
  1410		// Runs after the gate's deny check (a denied principal gets no preview) but
  1411		// before defer queues anything — a dry run must never create an approval.
  1412		if (args?.dry_run) {
  1413			const preview = await deleteEntity(entityId, force, env, ctx, {
  1414				dryRun: true,
  1415			});
  1416			return {
  1417				action: "delete",
  1418				success: true,
  1419				message:
  1420					deleteDecision.outcome === "defer"
  1421						? `${preview.message} (a real delete would be queued for approval)`
  1422						: preview.message,
  1423				deleted_count: 0,
  1424				dry_run: true,
  1425				tree: preview.tree,
  1426			};
  1427		}
