  1465	const RELATIONSHIP_SELECT = `
  1466	  r.id,
  1467	  r.organization_id,
  1468	  r.from_entity_id,
  1469	  r.to_entity_id,
  1470	  r.relationship_type_id,
  1471	  rt.slug as relationship_type_slug,
  1472	  rt.name as relationship_type_name,
  1473	  rt.is_symmetric,
  1474	  fe.name as from_entity_name,
  1475	  fet.slug as from_entity_type,
  1476	  te.name as to_entity_name,
  1477	  tet.slug as to_entity_type,
  1478	  r.metadata,
  1479	  r.confidence,
  1480	  r.source,
  1481	  r.created_by,
  1482	  r.updated_by,
  1483	  r.created_at,
  1484	  r.updated_at,
  1485	  r.deleted_at
  1486	`;
  1487	
  1488	const RELATIONSHIP_JOINS = `
  1489	  FROM entity_relationships r
  1490	  JOIN entity_relationship_types rt ON r.relationship_type_id = rt.id
  1491	  LEFT JOIN entities fe ON r.from_entity_id = fe.id
  1492	  LEFT JOIN entity_types fet ON fet.id = fe.entity_type_id
  1493	  LEFT JOIN entities te ON r.to_entity_id = te.id
  1494	  LEFT JOIN entity_types tet ON tet.id = te.entity_type_id
