  1498	// Relationship (Link) Action Handlers
  1499	// ============================================
  1500	
  1501	/**
  1502	 * Pre-image of an edge, read before unlink/update_link so the change log can
  1503	 * carry what the row held before the mutation. `RELATIONSHIP_SELECT` is the
  1504	 * caller-facing projection; this is the audit one.
  1505	 */
  1506	interface EdgeAuditRow {
  1507		id: number | string;
  1508		organization_id: string;
  1509		from_entity_id: number | string;
  1510		to_entity_id: number | string;
  1511		relationship_type_id: number | string;
  1512		metadata: unknown;
  1513		confidence: number | null;
  1514		source: string | null;
  1515		relationship_type_slug: string | null;
  1516		purpose: string | null;
  1517	}
  1518	
  1519	async function lockEdgeForMutation(
  1520		tx: DbClient,
  1521		relationshipId: number,
  1522		organizationId: string,
  1523		action: string,
  1524	): Promise<EdgeAuditRow> {
  1525		const rows = await tx<EdgeAuditRow>`
  1526	    SELECT r.id, r.organization_id, r.from_entity_id, r.to_entity_id,
  1527	           r.relationship_type_id, r.metadata, r.confidence, r.source,
  1528	           rt.slug AS relationship_type_slug, rt.purpose
  1529	    FROM entity_relationships r
  1530	    LEFT JOIN entity_relationship_types rt ON rt.id = r.relationship_type_id
  1531	    WHERE r.id = ${relationshipId} AND r.deleted_at IS NULL
  1532	    LIMIT 1
  1533	    FOR UPDATE OF r
  1534	  `;
  1535		if (rows.length === 0) {
  1536			throw new ToolUserError(`Relationship ${relationshipId} not found`, 404);
  1537		}
  1538		if (String(rows[0].organization_id) !== organizationId) {
  1539			throw new ToolUserError(
  1540				"Access denied: relationship belongs to another organization",
  1541				403,
  1542			);
  1543		}
  1544		// Both callers of this loader (unlink, update_link) mutate the edge, so the
  1545		// authorization guard belongs here rather than in each of them. Soft-deleting
  1546		// an ACL edge revokes access exactly as surely as creating one grants it.
  1547		assertNotAuthorizationType(
  1548			{ slug: rows[0].relationship_type_slug, purpose: rows[0].purpose },
  1549			action,
  1550		);
  1551		return rows[0];
  1552	}
