  1554	async function handleLink(
  1555		args: ManageEntityArgs,
  1556		env: Env,
  1557		ctx: ToolContext,
  1558	): Promise<ManageEntityResult> {
  1559		if (!args.from_entity_id)
  1560			throw new ToolUserError("from_entity_id is required for link", 400);
  1561		if (!args.to_entity_id)
  1562			throw new ToolUserError("to_entity_id is required for link", 400);
  1563		if (!args.relationship_type_slug)
  1564			throw new ToolUserError("relationship_type_slug is required for link", 400);
  1565	
  1566		const sql = getDb();
  1567	
  1568		validateNoSelfReference(args.from_entity_id, args.to_entity_id);
  1569		await validateScopeRule(args.from_entity_id, args.to_entity_id, env, ctx);
  1570	
  1571		// Schema search path for relationship types: tenant first, then any
  1572		// visibility='public' catalog. Mirrors createEntity's resolver so a tenant
  1573		// can use a canonical relationship type like `works_at` defined in
  1574		// public-uk-finance without registering a local copy. Tenant-local types
  1575		// win when both exist.
  1576		const typeRows = await sql`
  1577	    SELECT rt.id, rt.is_symmetric, rt.slug, rt.purpose
  1578	    FROM entity_relationship_types rt
  1579	    LEFT JOIN organization o ON o.id = rt.organization_id
  1580	    WHERE rt.slug = ${args.relationship_type_slug}
  1581	      AND rt.deleted_at IS NULL
  1582	      AND (
  1583	        rt.organization_id = ${ctx.organizationId}
  1584	        OR o.visibility = 'public'
  1585	      )
  1586	    ORDER BY (rt.organization_id = ${ctx.organizationId}) DESC, rt.id ASC
  1587	    LIMIT 1
  1588	  `;
  1589	  if (typeRows.length === 0) {
  1590			throw new ToolUserError(
  1591				`Relationship type "${args.relationship_type_slug}" not found`,
  1592				404,
  1593			);
  1594	  }
  1595	  // An authorization-bearing type is what the ACL gates read. Minting one of its
  1596	  // edges here would be minting access, so this surface refuses them outright —
  1597	  // classification is only a trust boundary if the classified rows stop being
  1598	  // generically writable.
  1599	  assertNotAuthorizationType(typeRows[0], 'link');
  1600	  const typeId = Number(typeRows[0].id);
  1601	  const isSymmetric = Boolean(typeRows[0].is_symmetric);
  1602	
  1603	  await validateTypeRule(typeId, args.from_entity_id, args.to_entity_id, sql);
  1604	
  1605	  let fromId = args.from_entity_id;
  1606	  let toId = args.to_entity_id;
  1607	  if (isSymmetric) {
  1608	    // For symmetric same-org pairs we canonicalize by id so dedup catches
  1609	    // a → b and b → a as the same edge. For cross-org pairs (target in a
  1610	    // public catalog), keep the caller's-org entity as `from` even if its
  1611	    // id is higher, so the stored source matches the semantic source. The
  1612	    // canonical form would otherwise leave rows where `from_entity_id`
  1613	    // points at a public catalog row under a tenant `organization_id` —
  1614	    // tenant-owned but cosmetically inverted.
  1615	    const orgRows = await sql<{ id: number; organization_id: string }>`
  1616	      SELECT id, organization_id FROM entities WHERE id IN (${fromId}, ${toId})
  1617	    `;
  1618			const orgOf = (id: number) =>
  1619				String(orgRows.find((r) => Number(r.id) === id)?.organization_id);
  1620			const sameOrg =
  1621				orgOf(fromId) === ctx.organizationId &&
  1622				orgOf(toId) === ctx.organizationId;
  1623			if (sameOrg) {
  1624				const canonical = canonicalizeSymmetricEdge(fromId, toId);
  1625				fromId = canonical.from;
  1626				toId = canonical.to;
  1627			}
  1628			// else: cross-org symmetric — preserve caller-from / public-to.
  1629			// validateScopeRule already required `from` to be in caller's org.
  1630		}
  1631	
  1632		await checkDuplicateEdge(fromId, toId, typeId, sql);
  1633	
  1634		validateConfidence(args.confidence);
  1635		validateSource(args.source);
  1636		const source = args.source ?? "api";
  1637		const confidence =
  1638			args.confidence ?? (source === "ui" || source === "api" ? 1.0 : null);
  1639	
  1640		const inserted = await sql`
  1641	    INSERT INTO entity_relationships (
  1642	      organization_id, from_entity_id, to_entity_id, relationship_type_id,
  1643	      metadata, confidence, source, created_by, updated_by,
  1644	      created_at, updated_at
  1645	    ) VALUES (
  1646	      ${ctx.organizationId},
  1647	      ${fromId},
  1648	      ${toId},
  1649	      ${typeId},
  1650	      ${args.metadata ? sql.json(args.metadata) : null},
  1651	      ${confidence},
  1652	      ${source},
  1653	      ${ctx.userId},
  1654	      ${ctx.userId},
  1655	      current_timestamp,
  1656	      current_timestamp
  1657	    )
  1658	    RETURNING id
  1659	  `;
  1660	  const relationshipId = Number((inserted[0] as { id: unknown }).id);
  1661	
  1662	  const created = await sql.unsafe<RelationshipRow>(
  1663	    `SELECT ${RELATIONSHIP_SELECT} ${RELATIONSHIP_JOINS} WHERE r.id = $1`,
  1664			[relationshipId],
  1665	  );
  1666	
  1667		recordEdgeChangeEvent({
  1668			organizationId: ctx.organizationId,
  1669			relationshipId,
  1670			fromEntityId: fromId,
  1671			toEntityId: toId,
  1672			relationshipTypeId: typeId,
  1673			relationshipTypeSlug: args.relationship_type_slug,
  1674			op: "link",
  1675			changes: [
  1676				{ field: "exists", old: false, new: true },
  1677				{ field: "metadata", old: null, new: args.metadata ?? null },
  1678				{ field: "confidence", old: null, new: confidence },
  1679				{ field: "source", old: null, new: source },
  1680			],
  1681			createdBy: ctx.userId,
  1682			clientId: ctx.clientId,
  1683		});
  1684	
  1685		return { action: "link", relationship: created[0] };
  1686	}
