  1737	async function handleUpdateLink(
  1738		args: ManageEntityArgs,
  1739		ctx: ToolContext,
  1740	): Promise<ManageEntityResult> {
  1741		if (!args.relationship_id)
  1742			throw new ToolUserError("relationship_id is required for update_link", 400);
  1743	
  1744	  const sql = getDb();
  1745	
  1746		const { before, after, updated } = await sql.begin(async (tx) => {
  1747			const edge = await lockEdgeForMutation(
  1748				tx,
  1749				args.relationship_id!,
  1750				ctx.organizationId,
  1751				"update_link",
  1752			);
  1753			validateConfidence(args.confidence);
  1754			validateSource(args.source);
  1755			const hasMetadata = args.metadata !== undefined;
  1756			const metadataChanged =
  1757				hasMetadata && stableJson(edge.metadata ?? null) !== stableJson(args.metadata ?? null);
  1758			// Check the locked pre-image so concurrent updates cannot move a reconciled
  1759			// edge out of the scope that retires it.
  1760			validateReconciledEdgeUpdate(edge.source, args.source, metadataChanged);
  1761			const metadataJson = hasMetadata ? tx.json(args.metadata) : null;
  1762			const updatedRows = await tx<{
  1763				metadata: unknown;
  1764				confidence: number | null;
  1765				source: string | null;
  1766			}>`
  1767	      UPDATE entity_relationships SET
  1768	        metadata = CASE
  1769	          WHEN ${hasMetadata} THEN ${metadataJson}
  1770	          ELSE metadata
  1771	        END,
  1772	        confidence = COALESCE(${args.confidence ?? null}, confidence),
  1773	        source = COALESCE(${args.source ?? null}, source),
  1774	        updated_by = ${ctx.userId},
  1775	        updated_at = current_timestamp
  1776	      WHERE id = ${args.relationship_id} AND deleted_at IS NULL
  1777	      RETURNING metadata, confidence, source
  1778	    `;
  1779			const relationship = await tx.unsafe<RelationshipRow>(
  1780				`SELECT ${RELATIONSHIP_SELECT} ${RELATIONSHIP_JOINS} WHERE r.id = $1`,
  1781				[args.relationship_id],
  1782			);
  1783			return {
  1784				before: edge,
  1785				after: updatedRows[0],
  1786				updated: relationship[0],
  1787			};
  1788		});
  1789	
  1790		const changes = [
  1791			{ field: "metadata", old: before.metadata, new: after.metadata },
  1792			{ field: "confidence", old: before.confidence, new: after.confidence },
  1793			{ field: "source", old: before.source, new: after.source },
  1794		].filter((c) => stableJson(c.old ?? null) !== stableJson(c.new ?? null));
  1795	
  1796		if (changes.length > 0) {
  1797			recordEdgeChangeEvent({
  1798				organizationId: ctx.organizationId,
  1799				relationshipId: Number(before.id),
  1800				fromEntityId: Number(before.from_entity_id),
  1801				toEntityId: Number(before.to_entity_id),
  1802				relationshipTypeId: Number(before.relationship_type_id),
  1803				relationshipTypeSlug: before.relationship_type_slug,
  1804				op: "update_link",
  1805				changes,
  1806				createdBy: ctx.userId,
  1807				clientId: ctx.clientId,
  1808			});
  1809		}
  1810	
  1811		return { action: "update_link", relationship: updated };
  1812	}
