   139	/**
   140	 * Entity read gate for agents/automations. Humans skip (role ACL is separate).
   141	 * Default is auto (unrestricted within org); a policy can deny by type.
   142	 */
   143	async function assertEntityReadAllowed(
   144		args: ManageEntityArgs | undefined,
   145		ctx: ToolContext,
   146		entityTypeSlug: string | null | undefined,
   147	): Promise<void> {
   148		const actor = await actingPrincipalFor(args, ctx);
   149		if (actor.kind === "user") return;
   150		const decision = await evaluateEntityMutation({
   151			organizationId: ctx.organizationId,
   152			principalKind: actor.kind,
   153			principalId: actor.id,
   154			ownerAgentId: actor.ownerAgentId,
   155			ownerResolved: actor.ownerResolved,
   156			action: "read",
   157			entityTypeSlug: entityTypeSlug ?? null,
   158			sql: getDb(),
   159		});
   160		if (decision === "deny") {
   161			const label = entityTypeSlug?.trim() || "this entity type";
   162			throw new ToolUserError(
   163				`Policy denies reading entities of type '${label}' for this principal.`,
   164				403,
   165			);
   166		}
   167	}
