   169	// ============================================
   170	// Main Function (Action Router)
     1	/**
     2	 * Entity merge — fold a duplicate `loser` entity into the `winner` it really is.
     3	 *
     4	 * The world-model keystone: when a bridge event (or a reviewer/automation) reveals
     5	 * two entities are the same real thing, this fuses them WITHOUT rewriting the
     6	 * append-only `events` table. It runs off the ingest hot path — a user-configured
     7	 * automation's agent, or an admin, calls it via `manage_entity(action='merge')`; the
     8	 * resolver only ever LOGS a "merge candidate", never fuses inline.
     9	 *
    10	 * Two disjoint event populations recall the winner afterward:
    11	 *   1. Identity/metadata-attributed events (connector-ingested): repaired HERE —
    12	 *      the loser's identities move to the winner, so the existing identity-graph
    13	 *      recall (entity_identities → events.metadata) finds them for free.
    14	 *   2. Raw `events.entity_ids`-stamped events (save_content memories, feed-pinned,
    15	 *      webhooks): can't be rewritten (append-only), so the loser stays as a
    16	 *      tombstone carrying `merged_into = winner`, and the recall redirect in
    17	 *      content-search/entity-link.ts gathers `{winner} ∪ {losers}` for the
    18	 *      `entity_ids @>` branch.
    19	 *
    20	 * Reversal uses the durable `entity_merge_operations` ledger to restore moved
    21	 * identities, canonical attributes, relationship endpoints, and flattened
    22	 * redirects. Undo fails closed when later edits no longer match that operation's
    23	 * after-state. Chains remain flattened (L→W→V stored as L→V, W→V) so reads stay
    24	 * one indexed hop; they must be undone from the outside in.
    25	 */
    26	
    27	import { isDeepStrictEqual } from "node:util";
    28	import { type DbClient, getDb, pgBigintArray } from "../db/client";
    29	import { mergeEntityState } from "../entity-resolution/merge-state";
    30	import {
    31		RESOLUTION_FINGERPRINT_VERSION,
    32		type ResolutionEvidence,
    33	} from "../entity-resolution/policy";
    34	import { assertResolutionFingerprintCurrent } from "../entity-resolution/staleness";
    35	import { transitionEntityMergeRows } from "./entity-management";
    36	import logger from "./logger";
    37	
    38	export interface MergeResolutionProvenance {
    39		decision: "auto_merge" | "human";
    40		sourceRunId?: number | null;
    41		automationId?: number | null;
    42		windowId?: number | null;
    43		policyHash?: string | null;
    44		evidence?: ResolutionEvidence[];
    45	}
    46	
    47	export interface ApplyMergeParams {
    48	  orgId: string;
    49	  /** The duplicate that gets tombstoned + forwarded. */
    50	  loserId: number;
    51	  /** The surviving entity that absorbs the loser. */
    52	  winnerId: number;
    53	  /** Who triggered the merge (agent id / user id) — for the tombstone audit. */
    54	  mergedBy: string;
    55		resolution?: MergeResolutionProvenance;
    56	}
    57	
    58	export interface ApplyMergeResult {
    59	  movedIdentities: number;
    60	  repointedEdges: number;
    61	}
    62	
    63	export interface ApplyMergeGroupResult {
    64	  mergedEntityIds: number[];
    65	  movedIdentities: number;
    66	  repointedEdges: number;
    67	}
    68	
    69	export interface ApplyMergeGroupParams {
    70	  orgId: string;
    71	  loserIds: number[];
    72	  winnerId: number;
    73	  mergedBy: string;
    74		resolution?: MergeResolutionProvenance;
    75		expectedResolutionFingerprint?: string;
    76	}
    77	
    78	/**
    79	 * Apply a whole duplicate group under one outer transaction. Any stale or
    80	 * invalid member rolls back every preceding member merge.
    81	 */
    82	export async function applyMergeGroup(
    83	  params: ApplyMergeGroupParams,
    84	  db: DbClient = getDb(),
    85	): Promise<ApplyMergeGroupResult> {
    86		return db.begin((tx) => applyMergeGroupInTransaction(params, tx));
    87	}
    88	
    89	export async function applyMergeGroupInTransaction(
    90	  params: ApplyMergeGroupParams,
    91	  tx: DbClient,
    92	): Promise<ApplyMergeGroupResult> {
    93	  const loserIds = [...new Set(params.loserIds)].sort((a, b) => a - b);
    94		if (loserIds.length === 0)
    95			throw new Error("applyMergeGroup: no duplicate entities");
    96	  if (loserIds.includes(params.winnerId)) {
    97			throw new Error("applyMergeGroup: canonical entity is also a duplicate");
    98	  }
    99	
   100	  // Lock the whole group in one global order before applying any member. Pairwise
   101	  // locking inside the loop is not sufficient: overlapping groups with different
   102	  // winners can otherwise each hold one entity while waiting for the other.
   103	  const entityIds = [...loserIds, params.winnerId].sort((a, b) => a - b);
   104	  await tx`
   105	    SELECT id
   106	    FROM entities
   107	    WHERE organization_id = ${params.orgId}
   108	      AND id = ANY(${pgBigintArray(entityIds)}::bigint[])
   109	    ORDER BY id
   110	    FOR UPDATE
   111	  `;
   112	
   113		if (params.expectedResolutionFingerprint) {
   114			await assertResolutionFingerprintCurrent(tx, {
   115				organizationId: params.orgId,
   116				winnerId: params.winnerId,
   117				loserIds,
   118				expectedFingerprint: params.expectedResolutionFingerprint,
   119				// Computed by this process moments ago, so it is current by
   120				// construction — never a stored digest from an older format.
   121				expectedVersion: RESOLUTION_FINGERPRINT_VERSION,
   122			});
   123		}
   124	
   125	  let movedIdentities = 0;
   126	  let repointedEdges = 0;
   127	  for (const loserId of loserIds) {
   128	    const result = await applyMergeInTransaction(
   129	      {
   130	        orgId: params.orgId,
   131	        loserId,
   132	        winnerId: params.winnerId,
   133	        mergedBy: params.mergedBy,
   134					resolution: params.resolution,
   135	      },
   136	      tx,
   137	    );
   138	    movedIdentities += result.movedIdentities;
   139	    repointedEdges += result.repointedEdges;
   140	  }
   141	  return { mergedEntityIds: loserIds, movedIdentities, repointedEdges };
   142	}
   143	
   144	/**
   145	 * Fuse `loser` into `winner` in one transaction. Idempotent-safe on re-run: a
   146	 * loser already merged into this winner returns a zero result rather than
   147	 * throwing. Throws on a cross-entity-type or already-merged-elsewhere conflict so
   148	 * the caller (tool) surfaces it rather than silently corrupting the graph.
   149	 */
   150	export async function applyMerge(
   151	  params: ApplyMergeParams,
   152	  db: DbClient = getDb(),
   153	): Promise<ApplyMergeResult> {
   154		return db.begin((tx) => applyMergeInTransaction(params, tx));
   155	}
   156	
   157	async function applyMergeInTransaction(
   158	  params: ApplyMergeParams,
   159	  tx: DbClient,
   160	): Promise<ApplyMergeResult> {
   161	  const { orgId, loserId, winnerId, mergedBy } = params;
   162	  if (loserId === winnerId) {
   163			throw new Error("applyMerge: loser and winner are the same entity");
   164	  }
   165	
   166	  // Lock both rows in a stable order (lowest id first) to avoid deadlocks when
   167	  // two merges touch the overlapping pair concurrently.
   168	  const [a, b] = loserId < winnerId ? [loserId, winnerId] : [winnerId, loserId];
   169	  const locked = await tx<{
   170	    id: number;
   171	    entity_type_id: number;
   172	    merged_into: number | null;
   173	    deleted_at: string | null;
   174			name: string;
   175			metadata: Record<string, unknown>;
   176			field_controls: Record<string, unknown>;
   177	  }>`
   178	    SELECT id, entity_type_id, merged_into, deleted_at, name, metadata, field_controls
   179	    FROM entities
   180	    WHERE organization_id = ${orgId} AND id IN (${a}, ${b})
   181	    ORDER BY id
   182	    FOR UPDATE
   183	  `;
   184	
   185	  const loser = locked.find((row) => Number(row.id) === loserId);
   186	  const winner = locked.find((row) => Number(row.id) === winnerId);
   187	  if (!loser || !winner) {
   188			throw new Error(
   189				`applyMerge: entity not found in org (loser=${loserId} winner=${winnerId})`,
   190			);
   191	  }
   192	  if (Number(loser.merged_into) === winnerId) {
   193	    return { movedIdentities: 0, repointedEdges: 0 };
   194	  }
   195	  if (loser.merged_into !== null) {
   196			throw new Error(
   197				`applyMerge: loser ${loserId} already merged into ${loser.merged_into}`,
   198			);
   199	  }
   200	  if (loser.deleted_at !== null) {
   201	    throw new Error(`applyMerge: loser ${loserId} is deleted`);
   202	  }
   203	  if (winner.merged_into !== null) {
   204			throw new Error(
   205				`applyMerge: winner ${winnerId} is itself merged into ${winner.merged_into}`,
   206			);
   207	  }
   208	  if (winner.deleted_at !== null) {
   209	    throw new Error(`applyMerge: winner ${winnerId} is deleted`);
   210	  }
   211	  if (Number(loser.entity_type_id) !== Number(winner.entity_type_id)) {
   212			throw new Error(
   213				"applyMerge: cannot merge entities of different entity types",
   214			);
   215	  }
   216	
   217		const identitiesBefore = await tx<{
   218			id: number;
   219			merged_from_entity_id: number | null;
   220		}>`
   221	    SELECT id, merged_from_entity_id
   222	    FROM entity_identities
   223	    WHERE organization_id = ${orgId}
   224	      AND entity_id = ${loserId}
   225	      AND deleted_at IS NULL
   226	    ORDER BY id
   227	    FOR UPDATE
   228	  `;
   229	
   230		const relationshipsBefore = await tx<{
   231			id: number;
   232			from_entity_id: number;
   233			to_entity_id: number;
   234			deleted_at: Date | string | null;
   235		}>`
   236	    SELECT id, from_entity_id, to_entity_id, deleted_at
   237	    FROM entity_relationships
   238	    WHERE organization_id = ${orgId}
   239	      AND deleted_at IS NULL
   240	      AND (from_entity_id = ${loserId} OR to_entity_id = ${loserId})
   241	    ORDER BY id
   242	    FOR UPDATE
   243	  `;
   244	
   245	  // 1. Move the loser's LIVE identities to the winner. A live loser↔live winner
   246	  //    collision on the SAME (org, namespace, identifier) is impossible — the
   247	  //    global unique index `idx_entity_identities_live_unique` forbids two live
   248	  //    rows for one value org-wide — so the move can never hit the index. Stamp
   249	  //    origin with COALESCE so an identity that already carries a marker (moved
   250	  //    here by an EARLIER merge, e.g. L→W then W→V) keeps its INNERMOST origin —
   251		//    the outer operation ledger can then put it back on W without losing L's
   252		//    provenance.
   253	  const moved = (await tx<{ id: number }>`
   254	    UPDATE entity_identities
   255	    SET entity_id = ${winnerId},
   256	        merged_from_entity_id = COALESCE(merged_from_entity_id, ${loserId}),
   257	        updated_at = current_timestamp
   258	    WHERE organization_id = ${orgId}
   259	      AND entity_id = ${loserId}
   260	      AND deleted_at IS NULL
   261	    RETURNING id
   262	  `) as Array<{ id: number }>;
   263	
   264		// 2. Merge complementary attributes. Scalar conflicts keep the canonical
   265		//    winner; arrays are unioned; missing fields and ownership markers move.
   266		//    The exact before/after pair is persisted below so Undo is lossless.
   267		const mergedState = mergeEntityState(
   268			{
   269				name: winner.name,
   270				metadata: winner.metadata ?? {},
   271				fieldControls: winner.field_controls ?? {},
   272			},
   273			{
   274				name: loser.name,
   275				metadata: loser.metadata ?? {},
   276				fieldControls: loser.field_controls ?? {},
   277			},
   278		);
   279		const updatedWinnerIds = await transitionEntityMergeRows({
   280			tx,
   281			organizationId: orgId,
   282			ids: [winnerId],
   283			expectedMergedInto: null,
   284			transition: {
   285				metadata: mergedState.metadata,
   286				fieldControls: mergedState.fieldControls,
   287			},
   288		});
   289		if (updatedWinnerIds.length !== 1) {
   290			throw new Error("applyMerge: canonical entity changed after locking");
   291		}
   292	
   293	  // 3. Tombstone loser edges that would become self-loops or collide with an
   294	  //    existing winner edge. This must happen before repointing: the live-edge
   295	  //    unique index rejects the collision during UPDATE, before a later cleanup
   296	  //    statement could run.
   297	  await tx`
   298	    UPDATE entity_relationships r
   299	    SET deleted_at = current_timestamp, updated_at = current_timestamp
   300	    WHERE r.organization_id = ${orgId}
   301	      AND r.deleted_at IS NULL
   302	      AND (r.from_entity_id = ${loserId} OR r.to_entity_id = ${loserId})
   303	      AND (
   304	        (CASE WHEN r.from_entity_id = ${loserId} THEN ${winnerId} ELSE r.from_entity_id END) =
   305	        (CASE WHEN r.to_entity_id = ${loserId} THEN ${winnerId} ELSE r.to_entity_id END)
   306	        OR EXISTS (
   307	          SELECT 1
   308	          FROM entity_relationships o
   309	          WHERE o.organization_id = ${orgId}
   310	            AND o.deleted_at IS NULL
   311	            AND o.id <> r.id
   312	            AND o.relationship_type_id = r.relationship_type_id
   313	            AND o.from_entity_id = CASE
   314	              WHEN r.from_entity_id = ${loserId} THEN ${winnerId}
   315	              ELSE r.from_entity_id
   316	            END
   317	            AND o.to_entity_id = CASE
   318	              WHEN r.to_entity_id = ${loserId} THEN ${winnerId}
   319	              ELSE r.to_entity_id
   320	            END
   321	        )
   322	      )
   323	  `;
   324	
   325	  // Repoint only the non-colliding live edges that remain.
   326	  const repointed = (await tx<{ id: number }>`
   327	    UPDATE entity_relationships
   328	    SET from_entity_id = CASE WHEN from_entity_id = ${loserId} THEN ${winnerId} ELSE from_entity_id END,
   329	        to_entity_id   = CASE WHEN to_entity_id   = ${loserId} THEN ${winnerId} ELSE to_entity_id   END,
   330	        updated_at = current_timestamp
   331	    WHERE organization_id = ${orgId}
   332	      AND deleted_at IS NULL
   333	      AND (from_entity_id = ${loserId} OR to_entity_id = ${loserId})
   334	    RETURNING id
   335	  `) as Array<{ id: number }>;
   336	
   337	  // 4. Flatten: anything that already pointed at the loser now points at the
   338	  //    winner, so every redirect stays exactly one hop (no chain walk at read).
   339	  //    The read redirect (`entity_ids && ARRAY(… merged_into = X …)`) is a
   340	  //    one-time indexed lookup even when X is an outer column, which a recursive
   341	  //    chain walk would NOT be on list/count/order call sites. The identities'
   342	  //    COALESCE'd `merged_from` markers (step 1) preserve reversibility that
   343	  //    the flattened `merged_into` pointer alone would lose. The funnel writes
   344	  //    an explicit id set, so the redirects are locked here first and the write
   345	  //    below re-asserts the topology this read proved.
   346		const redirectsToFlatten = await tx<{ id: number }>`
   347	    SELECT id
   348	    FROM entities
   349	    WHERE organization_id = ${orgId} AND merged_into = ${loserId}
   350	    ORDER BY id
   351	    FOR UPDATE
   352	  `;
   353		const redirectIds = redirectsToFlatten.map((entity) => Number(entity.id));
   354		const redirectedIds = await transitionEntityMergeRows({
   355			tx,
   356			organizationId: orgId,
   357			ids: redirectIds,
   358			expectedMergedInto: loserId,
   359			transition: { mergedInto: winnerId },
   360		});
   361		if (redirectedIds.length !== redirectIds.length) {
   362			throw new Error("applyMerge: redirect topology changed after locking");
   363		}
   364	
   365	  // 5. Tombstone the loser and point it at the winner.
   366		const tombstonedIds = await transitionEntityMergeRows({
   367			tx,
   368			organizationId: orgId,
   369			ids: [loserId],
   370			expectedMergedInto: null,
   371			transition: { mergedInto: winnerId, liveness: "deleted" },
   372		});
   373		if (tombstonedIds.length !== 1) {
   374			throw new Error("applyMerge: duplicate entity changed after locking");
   375		}
   376	
   377		const relationshipIds = relationshipsBefore.map((row) => Number(row.id));
   378		const relationshipsAfter =
   379			relationshipIds.length > 0
   380				? await tx<{
   381						id: number;
   382						from_entity_id: number;
   383						to_entity_id: number;
   384						deleted_at: Date | string | null;
   385					}>`
   386	        SELECT id, from_entity_id, to_entity_id, deleted_at
   387	        FROM entity_relationships
   388	        WHERE organization_id = ${orgId}
   389	          AND id = ANY(${pgBigintArray(relationshipIds)}::bigint[])
   390	        ORDER BY id
   391	      `
   392				: [];
   393		const afterById = new Map(
   394			relationshipsAfter.map((row) => [Number(row.id), row]),
   395		);
   396		const timestamp = (value: Date | string | null): string | null =>
   397			value === null ? null : new Date(value).toISOString();
   398		const ledger = {
   399			winner: {
   400				metadataBefore: winner.metadata ?? {},
   401				metadataAfter: mergedState.metadata,
   402				fieldControlsBefore: winner.field_controls ?? {},
   403				fieldControlsAfter: mergedState.fieldControls,
   404			},
   405			identities: identitiesBefore.map((identity) => ({
   406				id: Number(identity.id),
   407				mergedFromEntityId:
   408					identity.merged_from_entity_id == null
   409						? null
   410						: Number(identity.merged_from_entity_id),
   411			})),
   412			redirectedEntityIds: redirectedIds,
   413			relationships: relationshipsBefore.map((before) => {
   414				const after = afterById.get(Number(before.id));
   415				if (!after)
   416					throw new Error(`applyMerge: relationship ${before.id} disappeared`);
   417				return {
   418					id: Number(before.id),
   419					before: {
   420						fromEntityId: Number(before.from_entity_id),
   421						toEntityId: Number(before.to_entity_id),
   422						deletedAt: timestamp(before.deleted_at),
   423					},
   424					after: {
   425						fromEntityId: Number(after.from_entity_id),
   426						toEntityId: Number(after.to_entity_id),
   427						deletedAt: timestamp(after.deleted_at),
   428					},
   429				};
   430			}),
   610					)
   611				) {
   612					throw new Error(
   613						"applyUnmerge: canonical attributes changed after this merge; exact undo is unsafe",
   614					);
   615				}
   616	
   617				const identityIds = ledger.identities.map((item) => item.id);
   618				const currentIdentities =
   619					identityIds.length > 0
   620						? await tx<{
   621								id: number;
   622								entity_id: number;
   623								merged_from_entity_id: number | null;
   624								deleted_at: Date | string | null;
   625							}>`
   626	            SELECT id, entity_id, merged_from_entity_id, deleted_at
   627	            FROM entity_identities
   628	            WHERE organization_id = ${orgId}
   629	              AND id = ANY(${pgBigintArray(identityIds)}::bigint[])
   630	            ORDER BY id
   631	            FOR UPDATE
   632	          `
   633						: [];
   634				const currentIdentityById = new Map(
   635					currentIdentities.map((row) => [Number(row.id), row]),
   636				);
   637				for (const item of ledger.identities) {
   638					const current = currentIdentityById.get(item.id);
   639					const expectedMarker = item.mergedFromEntityId ?? loserId;
   640					if (
   641						!current ||
   642						Number(current.entity_id) !== winnerId ||
   643						Number(current.merged_from_entity_id) !== expectedMarker ||
   644						current.deleted_at !== null
   645					) {
   646						throw new Error(
   647							`applyUnmerge: identity ${item.id} changed after this merge; exact undo is unsafe`,
   648						);
   649					}
   650				}
   651	
   652				const relationshipIds = ledger.relationships.map((item) => item.id);
   653				const currentRelationships =
   654					relationshipIds.length > 0
   655						? await tx<{
   656								id: number;
   657								from_entity_id: number;
   658								to_entity_id: number;
   659								deleted_at: Date | string | null;
   660							}>`
   661	            SELECT id, from_entity_id, to_entity_id, deleted_at
   662	            FROM entity_relationships
   663	            WHERE organization_id = ${orgId}
   664	              AND id = ANY(${pgBigintArray(relationshipIds)}::bigint[])
   665	            ORDER BY id
   666	            FOR UPDATE
   667	          `
   668						: [];
   669				const currentById = new Map(
   670					currentRelationships.map((row) => [Number(row.id), row]),
   671				);
   672				for (const item of ledger.relationships) {
   673					const current = currentById.get(item.id);
   674					const currentDeletedAt =
   675						current?.deleted_at == null
   676							? null
   677							: new Date(current.deleted_at).toISOString();
   678					if (
   679						!current ||
   680						Number(current.from_entity_id) !== item.after.fromEntityId ||
   681						Number(current.to_entity_id) !== item.after.toEntityId ||
   682						currentDeletedAt !== item.after.deletedAt
   683					) {
   684						throw new Error(
   685							`applyUnmerge: relationship ${item.id} changed after this merge; exact undo is unsafe`,
   686						);
   687					}
   688				}
   689	
   690				for (const item of ledger.relationships) {
   691					await tx`
   692	          UPDATE entity_relationships
   693	          SET from_entity_id = ${item.before.fromEntityId},
   694	              to_entity_id = ${item.before.toEntityId},
   695	              deleted_at = ${item.before.deletedAt},
   696	              updated_at = current_timestamp
   697	          WHERE organization_id = ${orgId} AND id = ${item.id}
   698	        `;
   699				}
   700				const redirectedEntityIds = ledger.redirectedEntityIds ?? [];
   701				if (redirectedEntityIds.length > 0) {
   702					const restoredRedirects = await transitionEntityMergeRows({
   703						tx,
   704						organizationId: orgId,
   705						ids: redirectedEntityIds,
   706						expectedMergedInto: winnerId,
   707						transition: { mergedInto: loserId },
   708					});
