   716					tx,
   717					organizationId: orgId,
   718					ids: [winnerId],
   719					expectedMergedInto: null,
   720					transition: {
   721						metadata: ledger.winner.metadataBefore,
   722						fieldControls: ledger.winner.fieldControlsBefore,
   723					},
   724				});
   725				if (restoredWinnerIds.length !== 1) {
   726					throw new Error(
   727						"applyUnmerge: canonical topology changed after locking; exact undo is unsafe",
   728					);
   729				}
   730			}
   731	
   732			// 1. Restore every identity this operation moved, including identities an
   733			//    inner merge had already placed on the loser. Legacy operations have no
   734			//    ledger, so they retain the marker-based single-merge fallback.
