 667	/**
 668	 * Fold a duplicate entity (`entity_id`, the loser) into the one it really is
 669	 * (`winner_entity_id`). Humans must be admin/owner. Agents and automations may
 670	 * auto-merge only when the entity type policy proves the match; every other
 671	 * candidate queues human review. The heavy lifting (merge attributes, move
 672	 * identities and edges, tombstone + forward each loser, flatten chains) is in
 673	 * `applyMergeGroup`; this handler is the org-scoped gate + validation.
 674	 */
 675	async function handleMerge(
 676		args: ManageEntityArgs,
 677		ctx: ToolContext,
 678	): Promise<ManageEntityResult> {
 679		const actor = await actingPrincipalFor(args, ctx);
 680		if (actor.kind === "user" && !isAdminOrOwnerRole(ctx.memberRole)) {
 681			throw new ToolUserError("Only an admin or owner may merge entities", 403);
 682		}
 683		const loserIds = [
 684			...new Set(
 685				args.duplicate_entity_ids ?? (args.entity_id ? [args.entity_id] : []),
 686			),
 687		].sort((a, b) => a - b);
 688		const winnerId = args.winner_entity_id;
 689		if (loserIds.length === 0)
 690			throw new ToolUserError(
 691				"entity_id or duplicate_entity_ids is required for merge",
 692				400,
 693			);
 694		if (!winnerId)
 695			throw new ToolUserError(
 696				"winner_entity_id (the survivor) is required for merge",
 697				400,
 698			);
 699		if (loserIds.includes(winnerId))
 700			throw new ToolUserError("winner_entity_id cannot also be a duplicate", 400);
 701		if (loserIds.length > 25)
 702			throw new ToolUserError("A merge can include at most 25 duplicates", 400);
 703	
 704		const sql = getDb();
 705		// Every duplicate and the winner must be live and in the caller's org — never
 706		// merge across a tenant boundary or into a deleted/foreign entity.
 707		const rows = (await sql`
 708	    SELECT e.id, e.entity_type_id, e.metadata, et.metadata_schema,
 709	           et.slug AS entity_type_slug
 710	    FROM entities e
 711	    JOIN entity_types et ON et.id = e.entity_type_id
 712		WHERE e.organization_id = ${ctx.organizationId}
 713		      AND e.id = ANY(${pgBigintArray([...loserIds, winnerId])}::bigint[])
 714		      AND e.deleted_at IS NULL
 715		`) as Array<{
 716			id: number;
 717			entity_type_id: number;
 718			metadata: Record<string, unknown>;
 719			metadata_schema: Record<string, unknown> | null;
 720			entity_type_slug: string;
 721		}>;
 722		const found = new Set(rows.map((r) => Number(r.id)));
 723		for (const loserId of loserIds) {
 724			if (!found.has(loserId))
 725				throw new ToolUserError(
 726					`Entity ${loserId} not found in this workspace`,
 727					404,
 728				);
 729		}
 730		if (!found.has(winnerId))
 731			throw new ToolUserError(
 732				`Entity ${winnerId} not found in this workspace`,
 733				404,
 734			);
 735		const entityTypeIds = new Set(rows.map((row) => Number(row.entity_type_id)));
 736		if (entityTypeIds.size !== 1) {
 737			throw new ToolUserError(
 738				"Duplicate and canonical entities must have the same entity type",
 739				400,
 740			);
 741		}
 742	
 743		let resolution: ReturnType<typeof assessEntityResolution> | null = null;
 744		if (actor.kind !== "user") {
 745			const byId = new Map(rows.map((row) => [Number(row.id), row]));
 746			const winner = byId.get(winnerId);
 747			if (!winner) {
 748				throw new ToolUserError(
 749					`Entity ${winnerId} not found in this workspace`,
 750					404,
 751				);
 752			}
 753			const identities = await loadLiveEntityIdentities(sql, {
 754				organizationId: ctx.organizationId,
 755				entityIds: [...loserIds, winnerId],
 756			});
 757			resolution = assessEntityResolution({
 758				metadataSchema: winner.metadata_schema,
 759				entityTypeSlug: winner.entity_type_slug,
 760				winner: {
 761					id: winnerId,
 762					metadata: winner.metadata ?? {},
 763					identities: identities.get(winnerId) ?? [],
 764				},
 765				losers: loserIds.map((loserId) => ({
 766					id: loserId,
 767					metadata: byId.get(loserId)?.metadata ?? {},
 768					identities: identities.get(loserId) ?? [],
 769				})),
 770			});
 771		}
 772	
 773		if (actor.kind !== "user" && resolution?.decision === "review") {
 774			const attribution = attributionFor(actor);
 775			if (
 776				await wasResolutionRejected(sql, {
 777					organizationId: ctx.organizationId,
 778					fingerprint: resolution.fingerprint,
 779				})
 780			) {
 781				return {
 782					action: "merge",
 783					approval_suppressed: true,
 784					message:
 785						"This unchanged candidate was already rejected. It will be reconsidered when its evidence or policy changes.",
 786					resolution: {
 787						decision: "review",
 788						reason: resolution.reason,
 789						evidence: resolution.evidence,
 790					},
 791				};
 792			}
 793			const queued = await proposeEntityMerge(
 794				ctx,
 795				{
 796					entity_ids: loserIds,
 797					winner_entity_id: winnerId,
 798					evidence: resolution.evidence,
 799					automation_id:
 800						ctx.actingAutomationId ?? args.automation_source?.automation_id ?? null,
 801					window_id:
 802						ctx.actingWindowId ?? args.automation_source?.window_id ?? null,
 803					source_run_id: ctx.actingRunId ?? null,
 804					policy_hash: resolution.policyHash,
 805					resolution_fingerprint: resolution.fingerprint,
 806					resolution_fingerprint_version: RESOLUTION_FINGERPRINT_VERSION,
 807					attribution,
 808					reason: resolution.reason,
 809					// The proposer's own words, kept strictly separate from `reason` (the
 810					// machine-computed policy verdict). Displayed as a claim attributed to
 811					// whoever proposed the merge — it is never evidence and never affects
 812					// the auto-merge decision, which is recomputed server-side above.
 813					proposer_rationale: args.merge_rationale?.trim() || null,
 814				},
 815				resolution.resolutionKeys,
 816			);
 817			return {
 818				action: "merge",
 819				approval_queued: true,
 820				approval_url: queued.approvalUrl,
 821				approval_run_id: queued.runId,
 822				approval_action: "merge",
 823				approval_proposal: {
 824					entity_id: loserIds[0],
 825					entity_ids: loserIds,
 826					winner_entity_id: winnerId,
 827				},
 828				approval_attribution: attribution,
 829				next_steps: ["The merge is waiting for human approval."],
 830				resolution: {
 831					decision: "review",
 832					reason: resolution.reason,
 833					evidence: resolution.evidence,
 834				},
 835			};
 836		}
 837	
 838		let result: Awaited<ReturnType<typeof applyMergeGroup>>;
 839		try {
 840			result = await applyMergeGroup({
 841				orgId: ctx.organizationId,
 842				loserIds,
 843				winnerId,
 844				mergedBy: ctx.agentId ?? ctx.userId ?? "system",
 845				expectedResolutionFingerprint:
 846					actor.kind === "user" ? undefined : resolution?.fingerprint,
 847				resolution:
 848					actor.kind === "user"
 849						? {
 850								decision: "human",
 851								evidence: args.merge_evidence ?? [],
 852							}
 853						: {
 854								decision: "auto_merge",
 855								sourceRunId: ctx.actingRunId ?? null,
 856								automationId:
 857									ctx.actingAutomationId ??
 858									args.automation_source?.automation_id ??
 859									null,
 860								windowId:
 861									ctx.actingWindowId ??
 862									args.automation_source?.window_id ??
 863									null,
 864								policyHash: resolution?.policyHash ?? null,
 865								evidence: resolution?.evidence ?? [],
 866							},
 867			});
 868		} catch (err) {
 869			throw new ToolUserError(
 870				`Merge failed: ${err instanceof Error ? err.message : String(err)}`,
 871				409,
 872			);
 873		}
 874	
 875		return {
 876			action: "merge",
 877			success: true,
 878			message: `Merged ${loserIds.length} duplicate ${loserIds.length === 1 ? "entity" : "entities"} into ${winnerId} (${result.movedIdentities} identities moved, ${result.repointedEdges} edges re-pointed).`,
 879			winner_entity_id: winnerId,
 880			loser_entity_id: loserIds[0],
 881			loser_entity_ids: loserIds,
 882			moved_identities: result.movedIdentities,
 883			repointed_edges: result.repointedEdges,
 884			resolution: {
 885				decision: actor.kind === "user" ? "human" : "auto_merge",
 886				reason:
 887					actor.kind === "user"
 888						? "A workspace administrator confirmed the merge."
 889						: (resolution?.reason ?? "A deterministic identity rule matched."),
 890				evidence:
 891					actor.kind === "user"
 892						? (args.merge_evidence ?? [])
 893						: (resolution?.evidence ?? []),
 894			},
 895		};
 896	}
