 898	async function handleResolveDuplicates(
 899		args: ManageEntityArgs,
 900		ctx: ToolContext,
 901	): Promise<ManageEntityResult> {
 902		const candidateIds = [...new Set(args.candidate_entity_ids ?? [])].sort(
 903			(a, b) => a - b,
 904		);
 905		if (candidateIds.length < 2) {
 906			throw new ToolUserError(
 907				"candidate_entity_ids must contain at least two entities",
 908				400,
 909			);
 910		}
 911		let discovery: Awaited<ReturnType<typeof discoverWorkspaceResolutionGroups>>;
 912		try {
 913			discovery = await discoverWorkspaceResolutionGroups(getDb(), {
 914				organizationId: ctx.organizationId,
 915				candidateIds,
 916				maxGroups: 199,
 917				maxOperations: 199,
 918			});
 919		} catch (error) {
 920			throw new ToolUserError(
 921				error instanceof Error ? error.message : String(error),
 922				409,
 923			);
 924		}
 925	
 926		let autoMerged = 0;
 927		let approvalsQueued = 0;
 928		let approvalsSuppressed = 0;
 929		for (const group of discovery.groups) {
 930			for (const loserId of group.loserIds) {
 931				const result = await handleMerge(
 932					{
 933						action: "merge",
 934						winner_entity_id: group.winnerId,
 935						duplicate_entity_ids: [loserId],
 936					},
 937					ctx,
 938				);
 939				if ("success" in result && result.success) autoMerged += 1;
 940				else if ("approval_queued" in result && result.approval_queued) {
 941					approvalsQueued += 1;
 942				} else if (
 943					"approval_suppressed" in result &&
 944					result.approval_suppressed
 945				) {
 946					approvalsSuppressed += 1;
 947				}
 948			}
 949		}
 950	
 951		return {
 952			action: "resolve_duplicates",
 953			candidates_scanned: discovery.candidatesScanned,
 954			groups_found: discovery.groups.length,
 955			auto_merged: autoMerged,
 956			approvals_queued: approvalsQueued,
 957			approvals_suppressed: approvalsSuppressed,
 958			oversized_groups: discovery.oversizedGroupCount,
 959			deferred_candidates: discovery.deferredCandidateCount,
 960		};
 961	}
