1207	/**
1208	 * Force-delete dependency report: what a hard delete of the tree removes or
1209	 * detaches. Computed up front so `dry_run` can return it without mutating and
1210	 * the real delete can echo exactly what it touched. Event rows are append-only
1211	 * and are only ever detached, never deleted.
1212	 */
1213	export interface ForceDeleteTreeReport {
1214	  entities: number;
1215	  relationships: number;
1216	  automations_deleted: number;
1217	  automations_detached: number;
1218	  feeds_deleted: number;
1219	  feeds_detached: number;
1220	  events_detached: number;
1221	}
1222	
1223	/**
1224	 * Delete entity
1225	 * Soft delete by default (sets deleted_at), hard delete with force=true.
1226	 * A hard delete removes the tree + its relationships, deletes/detaches
1227	 * dependent automations and feeds, and detaches (never deletes) event rows that
1228	 * reference the tree. `dryRun` returns the dependency report without mutating.
1229	 * Requires write access (entity must belong to user's organization)
1230	 */
1231	export async function deleteEntity(
1232		entityId: number,
1233		force: boolean = false,
1234		env: Env,
1235		ctx: ToolContext,
1236		opts?: { skipHooks?: boolean; dryRun?: boolean },
1237	): Promise<{
1238	  message: string;
1239	  deleted: number;
1240	  dry_run?: boolean;
1241	  tree?: ForceDeleteTreeReport;
1242	}> {
1243	  const pgSql = createDbClientFromEnv(env);
1244	  const sql = getDb();
1245	
1246	  // Validate write access (uses PG for auth tables)
1247	  await requireWriteAccess(pgSql, entityId, ctx);
1248	
1249	  // Run beforeDelete hook (a dry run mutates nothing, so hooks stay silent)
1250	  if (!opts?.skipHooks && !opts?.dryRun) {
1251	    const entityRow = await sql`
1252	      SELECT et.slug AS entity_type, e.metadata
1253	      FROM entities e
1254	      JOIN entity_types et ON et.id = e.entity_type_id
1255	      WHERE e.id = ${entityId} AND e.deleted_at IS NULL
1256	    `;
1257	    if (entityRow.length > 0) {
1258	      const hooks = getEntityHooks(entityRow[0].entity_type as string);
1259	      if (hooks?.beforeDelete) {
1260	        await hooks.beforeDelete(
1261	          {
1262	            id: entityId,
1263	            entity_type: entityRow[0].entity_type as string,
1264	            metadata: entityRow[0].metadata as Record<string, unknown> | null,
1265	          },
1266	          { organizationId: ctx.organizationId, userId: ctx.userId }
1267	        );
1268	      }
1269	    }
1270	  }
1271	
1272	  // Check if entity has children
1273	  if (!force) {
1274	    const children = await sql`
1275	      SELECT COUNT(*) as count
1276	      FROM entities
1277	      WHERE parent_id = ${entityId}
1278	        AND deleted_at IS NULL
1279	    `;
1280	
1281	    const childCount = Number(children[0]?.count || 0);
1282	    if (childCount > 0) {
1283	      throw new Error(
1284	        `Cannot delete entity: it has ${childCount} child entities. Use force_delete_tree=true to delete the entire hierarchy.`
1285	      );
1286	    }
1287	  }
1288	
1289	  if (force) {
1290	    const entityTreeIds = await loadEntityTreeIds(sql, entityId);
1291	    const entityTreeIdsLiteral = pgBigintArray(entityTreeIds);
1292	
1293	    // Preflight dependency report: what this delete removes vs. detaches.
1294	    // An automation/feed whose entities all live inside the tree is deleted with
1295	    // it; one that also spans outside entities is detached (tree ids pruned
1296	    // from its entity_ids). Event rows are append-only history — they are
1297	    // counted here and DETACHED below, never deleted.
1298	    const preflight = await sql<Record<string, number>>`
1299	      SELECT
1300	        (SELECT COUNT(*) FROM entity_relationships r
1301	          WHERE r.from_entity_id = ANY(${entityTreeIdsLiteral}::bigint[])
1302	             OR r.to_entity_id = ANY(${entityTreeIdsLiteral}::bigint[]))::int AS relationships,
1303	        (SELECT COUNT(*) FROM automations w
1304	          WHERE w.entity_ids && ${entityTreeIdsLiteral}::bigint[]
1305	            AND w.entity_ids <@ ${entityTreeIdsLiteral}::bigint[])::int AS automations_deleted,
1306	        (SELECT COUNT(*) FROM automations w
1307	          WHERE w.entity_ids && ${entityTreeIdsLiteral}::bigint[]
1308	            AND NOT (w.entity_ids <@ ${entityTreeIdsLiteral}::bigint[]))::int AS automations_detached,
1309	        (SELECT COUNT(*) FROM feeds f
1310	          WHERE f.entity_ids && ${entityTreeIdsLiteral}::bigint[]
1311	            AND f.entity_ids <@ ${entityTreeIdsLiteral}::bigint[])::int AS feeds_deleted,
1312	        (SELECT COUNT(*) FROM feeds f
1313	          WHERE f.entity_ids && ${entityTreeIdsLiteral}::bigint[]
1314	            AND NOT (f.entity_ids <@ ${entityTreeIdsLiteral}::bigint[]))::int AS feeds_detached,
1315	        (SELECT COUNT(*) FROM events e
1316	          WHERE e.entity_ids && ${entityTreeIdsLiteral}::bigint[])::int AS events_detached
1317	    `;
1318	    const report: ForceDeleteTreeReport = {
1319	      entities: entityTreeIds.length,
1320	      relationships: Number(preflight[0]?.relationships || 0),
1321	      automations_deleted: Number(preflight[0]?.automations_deleted || 0),
1322	      automations_detached: Number(preflight[0]?.automations_detached || 0),
1323	      feeds_deleted: Number(preflight[0]?.feeds_deleted || 0),
1324	      feeds_detached: Number(preflight[0]?.feeds_detached || 0),
1325	      events_detached: Number(preflight[0]?.events_detached || 0),
1326	    };
1327	
1328	    if (opts?.dryRun) {
1329	      return {
1330	        message: `Dry run: force delete would remove ${report.entities} entities and detach ${report.events_detached} event rows`,
1331	        deleted: 0,
1332	        dry_run: true,
1333	        tree: report,
1334	      };
1335	    }
1336	
1337	    // Deletion predicate for automations/feeds: only rows whose entity set is
1338	    // non-empty AND fully inside the tree. Requiring the overlap (&&) first is
1339	    // load-bearing — a bare `entity_ids <@ tree` (or a COALESCE to '{}') also
1340	    // matches every empty/NULL-linked row IN EVERY ORG (empty set ⊂ anything),
1341	    // and lets the GIN index on entity_ids drive the scan instead of a
1342	    // full-table pass.
1343	    await sql.begin(async (tx) => {
1344	      await tx`
1345	        DELETE FROM entity_relationships
1346	        WHERE from_entity_id = ANY(${entityTreeIdsLiteral}::bigint[])
1347	           OR to_entity_id = ANY(${entityTreeIdsLiteral}::bigint[])
1348	      `;
1349	
1350	      // Canvas-on-events: window_id link rows carry canvas root event ids, so
