 62		      (${ABOUT_RELATIONSHIP_SLUG}, 'About', 'A chat channel is about a business entity',
 63		       ${organizationId}, false, NULL, current_timestamp, current_timestamp)
 64		    ON CONFLICT (organization_id, slug) WHERE status = 'active'
