 91	/** Team-scoped resource key + identity namespace for a chat channel.
 92	 *
 93	 * Connector-agnostic: a connector that registers a `ChannelReadIdentity`
 94	 * contributes both its channel identity namespace and the exact team-scoped key
 95	 * construction the ACL sync writes, so this names no platform. Connectors with
 96	 * no registered chat gate fall back to the generic `chat_channel_id` form. */
 97	export function channelResourceIdentity(
 98		connectorKey: string,
 99		teamId: string | null | undefined,
100		channelId: string,
101	): { namespace: string; key: string } {
102		const bare = channelId.includes(":")
103			? channelId.slice(channelId.indexOf(":") + 1)
104			: channelId;
105		const readIdentity = channelReadIdentityFor(connectorKey);
106		const key = readIdentity?.buildChannelKey(teamId, bare);
107		if (readIdentity && key) {
108			return { namespace: readIdentity.channelNamespace, key };
109		}
110		const team = teamId?.trim() || "";
250		const ids: number[] = [];
251		const slugs: string[] = [];
252		for (const ref of refs) {
253			if (typeof ref === "number" && Number.isFinite(ref)) ids.push(ref);
254			else if (typeof ref === "string" && ref.trim()) slugs.push(ref.trim());
255		}
256		const fromSlugs = await resolveEntitySlugsToIds(organizationId, slugs, sql);
257		return [...new Set([...ids, ...fromSlugs])];
258	}
