267	async function upsertAboutEdges(opts: {
268		organizationId: string;
269		fromChannelEntityId: number;
270		toBusinessEntityIds: number[];
271		source: string;
272		metadata: ChannelAboutMetadata;
273		userId: string | null | undefined;
274		typeId: number;
275		sql: DbClient;
276	}): Promise<void> {
277		// The partial conflict target only matches live rows; a tombstoned triple
278		// therefore gets a fresh live row, exactly as this path did before.
279		await upsertEdges({
280			db: opts.sql,
281			organizationId: opts.organizationId,
282			relationshipTypeId: opts.typeId,
283			pairs: opts.toBusinessEntityIds.map((toBusinessEntityId) => ({
284				fromEntityId: opts.fromChannelEntityId,
285				toEntityId: toBusinessEntityId,
286			})),
287			source: opts.source,
288			confidence: 1.0,
289			createdBy: opts.userId ?? null,
290			metadata: opts.metadata,
291			onConflict: 'update',
292		});
