300	export async function syncConnectionChannelAboutEdges(opts: {
301		organizationId: string;
302		connectionId: string | number;
303		connectorKey: string;
304		channels: ChannelAboutTarget[];
305		userId?: string | null;
306		sql?: DbClient;
307	}): Promise<{ linked: number; removed: number }> {
308		const sql = opts.sql ?? getDb();
309		const typeId = await ensureAboutRelationshipType(opts.organizationId, sql);
310		const connectionId = String(opts.connectionId);
311	
312		const desiredPairs = new Set<string>();
313		let linked = 0;
314	
315		for (const channel of opts.channels) {
316			const { key } = channelResourceIdentity(
317				opts.connectorKey,
318				channel.teamId,
319				channel.channelId,
320			);
321			const channelEntityId = await ensureChannelResourceEntity({
322				organizationId: opts.organizationId,
323				connectorKey: opts.connectorKey,
324				teamId: channel.teamId,
325				channelId: channel.channelId,
326				sql,
327			});
328			if (channelEntityId === null) {
329				logger.warn(
330					{
331						organization_id: opts.organizationId,
332						connection_id: connectionId,
333						channel_id: channel.channelId,
334					},
335					"Skipped channel about sync — channel entity could not be resolved",
336				);
337				continue;
338			}
339	
340			const metadata: ChannelAboutMetadata = {
341				connection_id: connectionId,
342				channel_key: key,
343			};
344	
345			for (const businessEntityId of channel.aboutEntityIds) {
346				desiredPairs.add(`${channelEntityId}:${businessEntityId}`);
347			}
348			await upsertAboutEdges({
349				organizationId: opts.organizationId,
350				fromChannelEntityId: channelEntityId,
351				toBusinessEntityIds: channel.aboutEntityIds,
352				source: EDGE_SOURCE_CONFIG,
353				metadata,
354				userId: opts.userId,
355				typeId,
356				sql,
357			});
358			linked += channel.aboutEntityIds.length;
359		}
360	
361		const existing = await sql<{
362			id: number;
363			from_entity_id: number;
364			to_entity_id: number;
365		}>`
366	    SELECT r.id, r.from_entity_id, r.to_entity_id
367	    FROM entity_relationships r
368	    WHERE r.organization_id = ${opts.organizationId}
369	      AND r.relationship_type_id = ${typeId}
370	      AND r.source = ${EDGE_SOURCE_CONFIG}
371	      AND r.deleted_at IS NULL
372	      AND r.metadata->>'connection_id' = ${connectionId}
373	  `;
374	
375		let removed = 0;
376		for (const row of existing) {
377			const pairKey = `${Number(row.from_entity_id)}:${Number(row.to_entity_id)}`;
378			if (desiredPairs.has(pairKey)) continue;
379			await sql`
380	      UPDATE entity_relationships
381	      SET deleted_at = current_timestamp, updated_at = current_timestamp
382	      WHERE id = ${row.id}
383	    `;
384			removed += 1;
385		}
386	
387		return { linked, removed };
388	}
