   244	          ? (result as any).entity.id
   245	          : args.entity_id;
   246	      await trackAutomationReaction({
   247	        organizationId: ctx.organizationId,
   248	        automationId: args.automation_source.automation_id,
   249	        windowId: args.automation_source.window_id,
