   271	async function handleCreate(
   272		args: ManageEntityArgs,
   273		env: Env,
   274		ctx: ToolContext,
   275	): Promise<ManageEntityResult> {
   276		if (!args.entity_type) {
   277			throw new ToolUserError("entity_type is required for create action", 400);
   278		}
   279	
   280		if (!args.name) {
   281			throw new ToolUserError("name is required for create action", 400);
   282		}
   283	
   284		// (Derived-type rejection lives in createEntity — the single chokepoint that
   285		// also resolves public-catalog types.)
   286	
   287		// Validate metadata against entity type's JSON schema (if defined)
   288		if (args.metadata && !isEmptyObject(args.metadata)) {
   289			const validation = await validateEntityMetadata(
   290				args.entity_type,
   291				args.metadata,
   292				ctx,
   293			);
   294			if (!validation.valid) {
   295				const errorMessages =
   296					validation.errors?.map((e) => e.message).join("; ") ??
   297					"Invalid metadata";
   298				throw new ToolUserError(`Metadata validation failed: ${errorMessages}`, 400);
   299			}
   300		}
   301	
   302		// Build entity data with organization_id from context
   303		const entityData: EntityData = {
   304			entity_type: args.entity_type,
   305			name: args.name,
   306			slug: args.slug,
   307			parent_id: args.parent_id ?? null,
   308			metadata: args.metadata ?? {},
   309			enabled_classifiers: args.enabled_classifiers ?? null,
   310			organization_id: ctx.organizationId,
   311		};
   312		(entityData as any).created_by = ctx.userId ?? "system";
   313	
   314		// All fields available on all entity types - DB constraints handle validation
   315		entityData.domain = args.domain ?? null;
   316		entityData.category = args.category ?? null;
   317		entityData.platform_type = args.platform_type ?? null;
   318		entityData.main_market = args.main_market ?? null;
   319		entityData.market = args.market ?? null;
   320		entityData.link = args.link ?? null;
   321	
   322		// Content body (used by memory entities)
   323		if (args.content !== undefined) {
   324			entityData.content = args.content;
   325		}
   326	
   327		const proposal = {
   328			entity_type: entityData.entity_type,
   329			name: entityData.name,
   330			parent_id: entityData.parent_id ?? null,
   331			metadata: entityData.metadata ?? {},
   332		};
   333		const actor = await actingPrincipalFor(args, ctx);
   334		const attribution = attributionFor(actor);
   335		const createDecision = await runMutationGate({
   336			action: "create",
   337			organizationId: ctx.organizationId,
   338			principalKind: actor.kind,
   339			sql: getDb(),
   340			attribution,
   341			// The TRUSTED reaction-session automation/window WINS (same precedence as
   342			// resolveActingPrincipal): a reaction can't retag its deferral into another
   343			// automation's approval batch by passing a foreign automation_source. The
   344			// caller-supplied source is only honored OUTSIDE a reaction session.
   345			automationId: ctx.actingAutomationId ?? args.automation_source?.automation_id ?? null,
   346			windowId: ctx.actingWindowId ?? args.automation_source?.window_id ?? null,
   347			principalId: actor.id,
   348			ownerAgentId: actor.ownerAgentId,
   349			ownerResolved: actor.ownerResolved,
   350			entityTypeSlug: args.entity_type,
   351			entityData,
   352			proposal,
   353		});
   354		if (createDecision.outcome === "deny") {
   355			throw new ToolUserError(createDecision.reason, 403);
   356		}
   357		if (createDecision.outcome === "defer") {
   358			const res = await createDecision.deferred.queue(ctx, env);
   359			return {
   360				action: "create",
   361				approval_queued: true,
   362				approval_url: res.approvalUrl,
   363				approval_run_id: res.runId,
   364				approval_action: "create",
   365				approval_proposal: proposal,
   366				approval_current: {},
   367				approval_attribution: attribution,
   368				next_steps: [
   369					`${capitalize(args.entity_type)} "${args.name}" is waiting for approval before it is created.`,
   370				],
   371			} as unknown as ManageEntityResult;
   372		}
   373	
   374		const entity = await createEntity(entityData, {
   375			hookContext: {
   376				organizationId: ctx.organizationId,
   377				userId: ctx.userId,
   378				env,
   379			},
   380		});
   381	
   382		const entityTypeLabel = capitalize(entity.entity_type);
   383	
   384		// Build next steps
   385		const nextSteps: string[] = [
   386			`${entityTypeLabel} "${entity.name}" created successfully with ID ${entity.id}.`,
   387		];
   388	
   389		if (!entity.parent_id) {
   390			// Root entity (no parent)
   391			nextSteps.push(
   392				`Use client.connections.connect({ connector_key: '<connector_key>' }), client.feeds.create({ connection_id: <connection_id>, feed_key: '<feed_key>', entity_ids: [${entity.id}], config: {} }) to target this entity, then client.feeds.trigger({ feed_id: <feed_id> }) to collect now.`,
   393				`Use client.automations.create({ entity_id: ${entity.id}, slug: '<slug>', agent_id: '<agent_id>', prompt: '<prompt>', sources: [], triggers: [{ kind: 'schedule', cron: '<cron>', timezone: '<IANA timezone>' }] }) to schedule an Automation.`,
   394			);
   395		} else {
   396			// Child entity (has parent)
   397			nextSteps.push(
   398				`${entityTypeLabel} belongs to ${entity.parent_name ? `"${entity.parent_name}"` : "parent"} (ID: ${entity.parent_id}).`,
   399				`Use client.connections.connect({ connector_key: '<connector_key>' }), client.feeds.create({ connection_id: <connection_id>, feed_key: '<feed_key>', entity_ids: [${entity.id}], config: {} }) to target this entity, then client.feeds.trigger({ feed_id: <feed_id> }) to collect now.`,
   400			);
   401		}
   402	
   403		const entityDetails = (await getEntity(entity.id, env, ctx)) ?? entity;
   404		const createdAtIso = toIsoStringOrNow(entityDetails.created_at);
   405		const viewUrl = await buildEntityViewUrl(ctx, entityDetails);
   406	
   407		return {
   408			action: "create",
   409			entity: {
   410				id: entityDetails.id,
   411				entity_type: entityDetails.entity_type,
   412				name: entityDetails.name,
   413				slug: entityDetails.slug,
   414				parent_id: entityDetails.parent_id,
   415				parent_name: entityDetails.parent_name,
   416				parent_slug: entityDetails.parent_slug ?? null,
   417				metadata: entityDetails.metadata ?? {},
   418				enabled_classifiers: entityDetails.enabled_classifiers,
   419				created_at: createdAtIso,
   420				view_url: viewUrl,
   421			},
   422			warnings: entity.warnings,
   423			next_steps: nextSteps,
   424		};
   425	}
