   427	async function handleUpdate(
   428		entityId: number,
   429		args: ManageEntityArgs,
   430		env: Env,
  1200		>
  1201	> {
  1202		if (!schema || entities.length === 0) return {};
  1203		const properties = (schema as { properties?: Record<string, any> })
  1204			.properties;
  1205		if (!properties) return {};
  1206	
  1207		// Collect (linkedType, lookupField) → set of referenced values from the rows.
  1208		const buckets = new Map<
  1209			string,
  1210			{ entityType: string; lookupField: string; values: Set<string> }
  1211		>();
  1212		for (const [columnKey, prop] of Object.entries(properties)) {
  1213			const linkedType = (prop as { "x-link-entity-type"?: unknown })[
  1214				"x-link-entity-type"
  1215			];
  1216			if (typeof linkedType !== "string" || linkedType === "") continue;
  1217			const lookupFieldRaw = (prop as { "x-link-lookup-field"?: unknown })[
  1218				"x-link-lookup-field"
  1219			];
  1220			const lookupField =
  1221				typeof lookupFieldRaw === "string" && lookupFieldRaw
  1222					? lookupFieldRaw
  1223					: "slug";
  1224			const bucketKey = `${linkedType}:${lookupField}`;
  1225			let bucket = buckets.get(bucketKey);
  1226			if (!bucket) {
  1227				bucket = { entityType: linkedType, lookupField, values: new Set() };
  1228				buckets.set(bucketKey, bucket);
  1229			}
  1230			for (const e of entities) {
  1231				const raw = e.metadata?.[columnKey];
  1232				const list = Array.isArray(raw) ? raw : [raw];
  1233				for (const v of list) {
  1234					if (v == null) continue;
  1235					const s = String(v).trim();
  1236					if (s !== "") bucket.values.add(s);
  1237				}
  1238			}
  1239		}
  1240		if (buckets.size === 0) return {};
  1241	
  1242		const sql = getDb();
  1243		const out: Record<
  1244			string,
  1245			Record<string, { slug: string; entity_type: string; name: string }>
  1246		> = {};
  1247	
  1248		await Promise.all(
  1249			[...buckets.entries()].map(
  1250				async ([bucketKey, { entityType, lookupField, values }]) => {
  1251					if (values.size === 0) return;
  1252					const valuesArr = [...values];
  1253					const valuesLiteral = pgTextArray(valuesArr);
  1254					const rows =
  1255						lookupField === "slug"
  1256							? await sql<{
  1257									slug: string;
  1258									entity_type: string;
  1259									name: string;
  1260									lookup_value: string;
  1261								}>`
  1262	              SELECT e.slug, et.slug AS entity_type, e.name, e.slug AS lookup_value
  1263	              FROM entities e
  1264	              JOIN entity_types et ON et.id = e.entity_type_id
  1265	              WHERE e.organization_id = ${organizationId}
  1266	                AND e.deleted_at IS NULL
  1267	                AND et.slug = ${entityType}
  1268	                AND e.slug = ANY(${valuesLiteral}::text[])
  1269	            `
  1270							: await sql<{
  1271									slug: string;
  1272									entity_type: string;
  1273									name: string;
  1274									lookup_value: string;
  1275								}>`
  1276	              SELECT e.slug, et.slug AS entity_type, e.name, (e.metadata->>${lookupField}) AS lookup_value
  1277	              FROM entities e
  1278	              JOIN entity_types et ON et.id = e.entity_type_id
  1279	              WHERE e.organization_id = ${organizationId}
  1280	                AND e.deleted_at IS NULL
  1281	                AND et.slug = ${entityType}
  1282	                AND (e.metadata->>${lookupField}) = ANY(${valuesLiteral}::text[])
  1283	            `;
  1284	      if (rows.length === 0) return;
  1285					const bucketMap: Record<
  1286						string,
  1287						{ slug: string; entity_type: string; name: string }
  1288					> = {};
  1289	      for (const r of rows) {
  1290	        if (r.lookup_value == null) continue;
  1291						bucketMap[r.lookup_value] = {
  1292							slug: r.slug,
  1293							entity_type: r.entity_type,
  1294							name: r.name,
  1295						};
  1296	      }
  1297	      out[bucketKey] = bucketMap;
  1298				},
  1299			),
  1300	  );
  1301	
  1302	  return out;
  1303	}
