  1365	async function handleDelete(
  1366		entityId: number,
  1367		force: boolean,
  1368		env: Env,
  1369		ctx: ToolContext,
  1370		args?: ManageEntityArgs,
  1371	): Promise<ManageEntityResult> {
  1372		// Get entity info before deletion
  1373		const entity = await getEntity(entityId, env, ctx);
  1374		if (!entity) {
  1375			throw new ToolUserError(`Entity with ID ${entityId} not found`, 404);
  1376		}
  1377	
  1378		const deleteActor = await actingPrincipalFor(args, ctx);
  1379		const attribution = attributionFor(deleteActor);
  1380		const current = {
  1381			id: entity.id,
  1382			entity_type: entity.entity_type,
  1383			name: entity.name,
  1384			slug: entity.slug,
  1385			parent_id: entity.parent_id,
  1386			metadata: entity.metadata ?? {},
  1387		};
  1388		const deleteDecision = await runMutationGate({
  1389			action: "delete",
  1390			organizationId: ctx.organizationId,
  1391			principalKind: deleteActor.kind,
  1392			sql: getDb(),
  1393			attribution,
  1394			// Trusted reaction-session automation/window WINS — see the create path.
  1395			automationId: ctx.actingAutomationId ?? args?.automation_source?.automation_id ?? null,
  1396			windowId: ctx.actingWindowId ?? args?.automation_source?.window_id ?? null,
  1397			principalId: deleteActor.id,
  1398			ownerAgentId: deleteActor.ownerAgentId,
  1399			ownerResolved: deleteActor.ownerResolved,
  1400			entityTypeSlug: entity.entity_type,
  1401			entityId,
  1402			entityOrgId: null,
  1403			forceDeleteTree: force,
  1404			current,
  1405		});
  1406		if (deleteDecision.outcome === "deny") {
  1407			throw new ToolUserError(deleteDecision.reason, 403);
  1408		}
  1409		// Preflight: report what the delete would remove/detach without mutating.
  1410		// Runs after the gate's deny check (a denied principal gets no preview) but
  1411		// before defer queues anything — a dry run must never create an approval.
  1412		if (args?.dry_run) {
  1413			const preview = await deleteEntity(entityId, force, env, ctx, {
  1414				dryRun: true,
  1415			});
  1416			return {
  1417				action: "delete",
  1418				success: true,
  1419				message:
  1420					deleteDecision.outcome === "defer"
  1421						? `${preview.message} (a real delete would be queued for approval)`
  1422						: preview.message,
  1423				deleted_count: 0,
  1424				dry_run: true,
  1425				tree: preview.tree,
  1426			};
  1427		}
  1428		if (deleteDecision.outcome === "defer") {
  1429			const res = await deleteDecision.deferred.queue(ctx, env);
  1430			return {
  1431				action: "delete",
  1432				success: false,
  1433				message: `Delete queued for approval: ${entity.name}`,
  1434				deleted_count: 0,
  1435				approval_queued: true,
  1436				approval_url: res.approvalUrl,
  1437				approval_run_id: res.runId,
  1438				approval_action: "delete",
  1439				approval_proposal: {
  1440					entity_id: entity.id,
  1441					entity_type: entity.entity_type,
  1442					name: entity.name,
  1443					force_delete_tree: force,
  1444				},
  1445				approval_current: current,
  1446				approval_attribution: attribution,
  1447			} as ManageEntityResult;
  1448		}
  1449	
  1450		const result = await deleteEntity(entityId, force, env, ctx);
  1451	
  1452		return {
  1453			action: "delete",
  1454			success: true,
  1455			message: result.message,
  1456			deleted_count: result.deleted,
  1457			tree: result.tree,
  1458		};
  1459	}
