   681	async function loadEntityTreeIds(sql: DbClient, entityId: number): Promise<number[]> {
   682	  const rows = await sql<{ id: number }>`
   683	    WITH RECURSIVE entity_tree AS (
   684	      SELECT id
   685	      FROM entities
   686	      WHERE id = ${entityId}
   687	      UNION ALL
   688	      SELECT e.id
   689	      FROM entities e
   690	      JOIN entity_tree et ON e.parent_id = et.id
   691	    )
   692	    SELECT id
   693	    FROM entity_tree
   694	  `;
   695	
   696	  return rows.map((row) => Number(row.id));
   697	}
